package db

import "fmt"

// Difficulty levels for beginner-friendly categorization.
const (
	DiffNakedEye       = "Naked Eye"       // Visible without equipment
	DiffBinoculars     = "Binoculars"      // Easy with binoculars or finder scope
	DiffSmallTelescope = "Small Telescope"  // Needs a small telescope (60-80mm)
	DiffAdvanced       = "Advanced"         // Needs good equipment and/or dark skies
)

// SeedBuiltinCatalog populates the database with well-known astronomical objects
// including all 110 Messier objects, bright named stars, and selected Caldwell objects.
// Safe to call multiple times — uses INSERT OR IGNORE.
func (s *Store) SeedBuiltinCatalog() (int, error) {
	objects := make([]CelestialObject, 0, 1000)
	objects = append(objects, messierCatalog()...)
	objects = append(objects, namedStarsExtended()...)
	objects = append(objects, caldwellComplete()...)
	objects = append(objects, doubleStars()...)
	objects = append(objects, variableStars()...)
	objects = append(objects, herschelSelection()...)
	objects = append(objects, icObjects()...)
	objects = append(objects, solarSystemObjects()...)

	n, err := s.BulkInsert(objects)
	if err != nil {
		return 0, fmt.Errorf("seed catalog: %w", err)
	}
	return n, nil
}

// IsCatalogSeeded returns true if the built-in catalog has already been loaded.
func (s *Store) IsCatalogSeeded() bool {
	var count int
	s.db.QueryRow("SELECT COUNT(*) FROM celestial_objects").Scan(&count)
	return count >= 500
}

func obj(name, catID, typ string, ra, dec, mag, size float64, cat, diff, desc string) CelestialObject {
	return CelestialObject{
		Name: name, CatalogID: catID, Type: typ,
		RADeg: ra, DecDeg: dec, Magnitude: mag, SizeArcMin: size,
		Category: cat, Difficulty: diff, Description: desc,
	}
}

